import{z as A,x as B,o as r,c as p,q as i,j as n,D as e,d as t,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"流量工程","description":"","frontmatter":{"title":"流量工程","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/traffic-engineering.md","filePath":"cs/traffic-engineering.md","lastUpdated":1791063341000}'),d={name:"cs/traffic-engineering.md"};function P(T,E,C,D,F,m){const s=B("Mermaid");return r(),p("div",null,[E[2]||(E[2]=i('<h1 id="流量工程" tabindex="-1">流量工程 <a class="header-anchor" href="#流量工程" aria-label="Permalink to &quot;流量工程&quot;">​</a></h1><div class="epigraph"><p>最短 IGP 度量会把流量堆到最宽的树上；流量工程用另一套约束（带宽、时延、着色）把需求矩阵搬到链路上，使热点下降。</p><footer>—— 据 RFC 3272 综述；OSPF-TE / RSVP-TE 实践；Kurose and Ross TE 节整理</footer></div><p><a href="/cs/internet-ixp">上一课</a> 画出 AS 图。域内同样会挤：ECMP 哈希仍可能打满一条。缺口是<strong>流量工程</strong>：与「最短路」分离的显式路由或度量调整。本课不把 MPLS 标签栈写完，下一课才是 MPLS。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OSPF 代价若只按接口带宽设，所有需求仍可能共享同一条低代价边。TE：测量需求 → 算约束最短路或多商品流近似 → 用 RSVP-TE 建 LSP，或调 IGP 度量，或用后课 SR。目标常是最大链路利用率最小，不是单流跳数最小。与 HOL：那是微秒级结构；TE 是分钟到小时的矩阵。</p><p><span class="marginnote">术语翻译：流量工程就是给路网装导航——不把路修宽，而是让车流按「哪条路还空着」分流；优化目标常是「最挤的那条路别太挤」，而不是让每辆车跳数最少。</span></p><p>不要把 TE 写成「买更大的口」唯一解：口更大后最短树仍可能挤。</p><p><span class="marginnote">RFC 3272。Fortz–Thorup 等讨论度量优化。本课不解整数多商品流。</span></p><h3 id="最短树会堆热点" tabindex="-1">最短树会堆热点 <a class="header-anchor" href="#最短树会堆热点" aria-label="Permalink to &quot;最短树会堆热点&quot;">​</a></h3><p>度量、LSP 或 SR 把需求矩阵搬开。过频调度量会抖 IGP。域间 TE 是属性，不是 Dijkstra。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：调度量（全局副作用）vs 显式 LSP（局部）。画：需求矩阵 → 约束 → 转发路径。IXP 出口选择是域间 TE：MED、AS-PATH prepend、更长前缀（谨慎，RPKI maxLength）。</p><p><span class="marginnote">数字实例：两条 10G 链路用 ECMP 分流，但哈希只认五元组——一旦六成流量来自同一条大象流，哈希再均匀，那一条照样被打满。这就是「ECMP 不是 TE」的原因。</span></p>',13)),(r(),n(o,null,{default:e(()=>[l(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEM%5B%22%E9%9C%80%E6%B1%82%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20CST%5B%22%E5%B8%A6%E5%AE%BD%2F%E6%97%B6%E5%BB%B6%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20CST%20--%3E%20PATH%5B%22%E6%98%BE%E5%BC%8F%E6%88%96%E8%B0%83%E5%BA%A6%E9%87%8F%22%5D%0A%20%20PATH%20--%3E%20UTIL%5B%22%E9%99%8D%E7%83%AD%E7%82%B9%E5%88%A9%E7%94%A8%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"BGP 决策仍选出口；TE 决定出口之后域内怎么走。卫星链路带宽贵，TE 更要避开误码高的入口。切片 5G 是无线侧预留；这里是 IP/MPLS 预留，对象类似、层不同。",-1)),E[5]||(E[5]=a("p",null,"ECMP 是无状态分流，TE 可以有状态；后课会对比 SR 的无状态中间节点。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"常见误区：以为扩容就能消热点。带宽加大后最短路径树还是那棵树，需求仍往同一条边上堆——往往先把流量搬开再谈扩容，反而更省钱。")],-1)),(r(),n(o,null,{default:e(()=>[l(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20FA%5B%22%E6%B5%81%20A%EF%BC%9A8%20Gbps%22%5D%20--%3E%20L1%7B%22%E9%83%BD%E9%80%89%E4%B8%AD%E5%90%8C%E4%B8%80%E6%9D%A1%EF%BC%9Cbr%2F%EF%BC%9E10%20Gbps%20%E6%9C%80%E7%9F%AD%E8%B7%AF%22%7D%0A%20%20FB%5B%22%E6%B5%81%20B%EF%BC%9A7%20Gbps%3Cbr%2F%3E%E4%B9%9F%E9%80%89%E5%90%8C%E4%B8%80%E6%9D%A1%E6%9C%80%E7%9F%AD%E8%B7%AF%22%5D%20--%3E%20L1%0A%20%20L1%20--%3E%20HOT%5B%22%E5%90%88%E8%AE%A1%2015%20Gbps%3Cbr%2F%3E%E5%88%A9%E7%94%A8%E7%8E%87%20150%25%EF%BC%8C%E6%8E%92%E9%98%9F%E4%B8%A2%E5%8C%85%22%5D%0A%20%20HOT%20--%3E%20TE%5B%22TE%20%E6%8C%89%E7%BA%A6%E6%9D%9F%E9%87%8D%E7%AE%97%3Cbr%2F%3E%E6%8A%8A%20B%20%E5%BC%95%E4%B8%8A%E7%A9%BA%E4%BD%99%E9%93%BE%E8%B7%AF%22%5D%0A%20%20TE%20--%3E%20OK%5B%22A%20%E5%8E%9F%E8%B7%AF%E5%88%A9%E7%94%A8%E7%8E%87%2080%25%3Cbr%2F%3EB%20%E7%BB%95%E8%A1%8C%E9%93%BE%E8%B7%AF%E5%88%A9%E7%94%A8%E7%8E%87%2070%25%3Cbr%2F%3E%E4%B8%A4%E6%9D%A1%E9%83%BD%E4%B8%8D%E7%82%B8%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 PCE 的全部 PCEP。MPLS 是下一课。后课默认：TE 把约束放进选路，IGP 最短只是其中一个解。</p><p>过频调度量会引起 IGP 与 BGP 震荡，像人为抖动。</p><p>下一课<a href="/cs/mpls">MPLS</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最短 IGP 树不等于均衡负载。</li><li>TE 用度量、LSP 或后课 SR 搬流量。</li><li>域间 TE 是政策属性，不是 Dijkstra。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 3272；OSPF-TE 实践。</li></ul>',6))])}const S=A(d,[["render",P]]);export{h as __pageData,S as default};
